#include "../Sources/RDPClipboardCore.h"
#include <winpr/clipboard.h>
#include <openssl/evp.h>
#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
static cJSON* last;static int states,reads,offers,requests,lists,responses;static CLIPRDR_FORMAT_DATA_RESPONSE sent;
static BYTE received[128];static void emit(void* p,cJSON* obj){(void)p;const char* type=cJSON_GetObjectItem(obj,"type")->valuestring;if(!strcmp(type,"clipboardState"))states++;else{if(last)cJSON_Delete(last);last=cJSON_Duplicate(obj,1);if(!strcmp(type,"clipboardReadResult"))reads++;else offers++;}cJSON_Delete(obj);}
static UINT caps(CliprdrClientContext* c,const CLIPRDR_CAPABILITIES* p){(void)c;assert(p->cCapabilitiesSets==1);const CLIPRDR_GENERAL_CAPABILITY_SET* general=(const CLIPRDR_GENERAL_CAPABILITY_SET*)p->capabilitySets;assert(general->generalFlags==CB_USE_LONG_FORMAT_NAMES);return 0;}
static UINT list_ack(CliprdrClientContext* c,const CLIPRDR_FORMAT_LIST_RESPONSE* p){(void)c;assert(p->common.msgFlags==CB_RESPONSE_OK);return 0;}
static UINT read_request(CliprdrClientContext* c,const CLIPRDR_FORMAT_DATA_REQUEST* p){(void)c;assert(p->requestedFormatId==CF_UNICODETEXT);requests++;return 0;}
static UINT format_list(CliprdrClientContext* c,const CLIPRDR_FORMAT_LIST* p){(void)c;assert(p->numFormats==1&&p->formats[0].formatId==CF_UNICODETEXT);lists++;return 0;}
static UINT data_sent(CliprdrClientContext* c,const CLIPRDR_FORMAT_DATA_RESPONSE* p){(void)c;sent=*p;if(p->common.dataLen){assert(p->common.dataLen<=sizeof(received));memcpy(received,p->requestedFormatData,p->common.dataLen);}responses++;return 0;}
static int ok(void){assert(last);return cJSON_IsTrue(cJSON_GetObjectItem(last,"ok"));}
