 BYTE value[]={'a',0,0x2d,0x4e,0x3d,0xd8,0x00,0xde,0,0,0,0};size_t length=0;assert(mt_clip_validate(value,sizeof(value),&length)&&length==10);BYTE bad[][6]={{0,0,1,0,0,0},{0x00,0xdc,0,0,0,0},{0x00,0xd8,'x',0,0,0},{'a',0,'b',0,'c',0}};for(size_t i=0;i<4;i++)assert(!mt_clip_validate(bad[i],6,NULL));assert(!mt_clip_validate(value,3,NULL));
 BYTE* boundary=calloc(MT_CLIP_WIRE_MAX+2,1);assert(boundary);for(size_t i=0;i<MT_CLIP_UTF8_MAX;i++)boundary[2*i]='a';assert(mt_clip_validate(boundary,MT_CLIP_WIRE_MAX,NULL));boundary[MT_CLIP_WIRE_MAX-2]='a';assert(!mt_clip_validate(boundary,MT_CLIP_WIRE_MAX+2,NULL));free(boundary);
 MTClipboard clip;mt_clip_init(&clip,NULL,emit,FALSE);CliprdrClientContext channel={.ClientCapabilities=caps,.ClientFormatListResponse=list_ack,.ClientFormatDataRequest=read_request,.ClientFormatList=format_list,.ClientFormatDataResponse=data_sent};mt_clip_attach(&clip,&channel);CLIPRDR_GENERAL_CAPABILITY_SET general={.capabilitySetType=CB_CAPSTYPE_GENERAL,.capabilitySetLength=12,.generalFlags=CB_USE_LONG_FORMAT_NAMES|CB_STREAM_FILECLIP_ENABLED|CB_CAN_LOCK_CLIPDATA};CLIPRDR_CAPABILITIES capabilities={.cCapabilitiesSets=1,.capabilitySets=(CLIPRDR_CAPABILITY_SET*)&general};assert(channel.ServerCapabilities(&channel,&capabilities)==0);CLIPRDR_MONITOR_READY ready={0};assert(channel.MonitorReady(&channel,&ready)==0&&clip.ready&&lists==0);/* No initial local clipboard announcement. */
 CLIPRDR_FORMAT format={.formatId=CF_UNICODETEXT};CLIPRDR_FORMAT_LIST list={.numFormats=1,.formats=&format};assert(channel.ServerFormatList(&channel,&list)==0&&clip.remoteText&&requests==0);mt_clip_read(&clip,1);assert(requests==1&&clip.readID==1);CLIPRDR_FORMAT_DATA_RESPONSE response={.common.msgFlags=CB_RESPONSE_OK,.common.dataLen=sizeof(value),.requestedFormatData=value};assert(channel.ServerFormatDataResponse(&channel,&response)==0&&ok()&&reads==1&&!clip.readID);const char* encoded=cJSON_GetObjectItem(last,"data")->valuestring;assert(strlen(encoded)==16);
 mt_clip_read(&clip,2);assert(channel.ServerFormatList(&channel,&list)==0);assert(channel.ServerFormatDataResponse(&channel,&response)==0&&!ok()&&reads==2);mt_clip_read(&clip,3);clip.readDeadline=1;mt_clip_tick(&clip);assert(!ok()&&clip.readBlocked&&clip.readID==0);assert(channel.ServerFormatDataResponse(&channel,&response)==0&&reads==3);mt_clip_read(&clip,4);assert(!ok()&&requests==3);/* A late response cannot attach to a new read. */
 char encodedOffer[32];EVP_EncodeBlock((unsigned char*)encodedOffer,value,10);mt_clip_offer(&clip,5,encodedOffer);assert(lists==1&&clip.offerID==5);CLIPRDR_FORMAT_LIST_RESPONSE ack={.common.msgFlags=CB_RESPONSE_OK};assert(channel.ServerFormatListResponse(&channel,&ack)==0&&ok());CLIPRDR_FORMAT_DATA_REQUEST request={.requestedFormatId=CF_UNICODETEXT};assert(channel.ServerFormatDataRequest(&channel,&request)==0&&sent.common.msgFlags==CB_RESPONSE_OK&&sent.common.dataLen==10&&!memcmp(value,received,10));request.requestedFormatId=1;assert(channel.ServerFormatDataRequest(&channel,&request)==0&&sent.common.msgFlags==CB_RESPONSE_FAIL);
 mt_clip_offer(&clip,6,encodedOffer);channel.ServerFormatList(&channel,&list);channel.ServerFormatListResponse(&channel,&ack);assert(!ok()&&!clip.offered&&!clip.offerID&&!clip.offerBlocked);mt_clip_offer(&clip,7,"AAAA!!!!");assert(!ok()&&!clip.offered);mt_clip_offer(&clip,8,encodedOffer);clip.offerDeadline=1;mt_clip_tick(&clip);assert(!ok()&&clip.offerBlocked&&!clip.offered);int count=offers;channel.ServerFormatListResponse(&channel,&ack);assert(offers==count);
 mt_clip_detach(&clip);assert(!clip.ready&&!clip.readBlocked&&!clip.offerBlocked);clip.readOnly=TRUE;mt_clip_attach(&clip,&channel);channel.ServerCapabilities(&channel,&capabilities);channel.MonitorReady(&channel,&ready);channel.ServerFormatList(&channel,&list);mt_clip_offer(&clip,9,encodedOffer);assert(!ok()&&!clip.offered);mt_clip_read(&clip,10);assert(clip.readID==10);mt_clip_detach(&clip);assert(!ok()&&!clip.readID);mt_clip_destroy(&clip);if(last)cJSON_Delete(last);assert(states>0&&responses==2);
 puts("PASS: RDP clipboard Unicode/size/NUL bounds, no automatic data fetch/announcement, text-only capabilities, read-only receive, fixed revision, acknowledgement, stale response/timeout blocking, cancellation and channel cleanup");return 0;
